begin;
do $$
declare boss uuid:=gen_random_uuid();emp uuid:=gen_random_uuid();admin_user uuid:=gen_random_uuid();c uuid;w uuid;l uuid;d uuid;j uuid;s uuid;budget uuid;estimate public.essential_budget_evaluations;denied boolean;
begin
 insert into auth.users(id,email,email_confirmed_at) values(boss,boss||'@budget.test.invalid',now()),(emp,emp||'@budget.test.invalid',now()),(admin_user,admin_user||'@budget.test.invalid',now());perform set_config('request.jwt.claim.sub',boss::text,true);c:=public.create_company_for_edition('Labor budget fixture','essential');update public.companies set is_test=true,billing_mode='test_simulated',billing_status='active',seat_limit=10 where id=c;insert into private.essential_test_plans(company_id,snapshot) select c,to_jsonb(p) from public.essential_plans p where id='essential_pro';
 insert into public.company_members(company_id,user_id,role) values(c,emp,'employee'),(c,admin_user,'admin');select id into w from public.company_workers where company_id=c and auth_user_id=emp;select id into l from public.essential_locations where company_id=c;select default_punch_job_id into j from public.companies where id=c;d:=public.save_essential_department(c,l,'Budget department');perform public.assign_essential_worker(w,l,d);
 perform public.save_essential_pay_rule(c,0,'2026-10-19','America/Toronto',40,1.5,'[]','Synthetic estimate validation');perform public.add_essential_pay_rate(c,w,'2026-10-19',2500,'Synthetic rate');
 insert into public.punch_sessions(company_id,user_id,worker_id,started_at,ended_at) values(c,emp,w,'2026-10-20 08:00-04','2026-10-20 16:00-04') returning id into s;insert into public.punch_segments(company_id,session_id,job_id,started_at,ended_at) values(c,s,j,'2026-10-20 08:00-04','2026-10-20 16:00-04');
 execute 'set local role authenticated';budget:=public.save_essential_labor_budget(c,d,'2026-10-19',15000,0,'Synthetic budget');estimate:=public.evaluate_essential_labor_budget(budget);
 if (estimate.payload->>'estimated_cents')::numeric<>20000 or (estimate.payload->>'variance_cents')::numeric<>5000 or (estimate.payload->>'incomplete')::boolean then raise exception 'Budget cost comparison incorrect';end if;
 denied:=false;begin perform public.save_essential_labor_budget(c,d,'2026-10-19',9000,0,'Stale budget');exception when others then denied:=true;end;if not denied then raise exception 'Budget stale version accepted';end if;
 perform public.save_essential_labor_budget(c,d,'2026-10-19',25000,1,'Revised budget');if (estimate.payload->>'budget_cents')::numeric<>15000 then raise exception 'Old comparison mutated';end if;
 execute 'reset role';delete from public.essential_pay_rates where company_id=c and worker_id=w;execute 'set local role authenticated';estimate:=public.evaluate_essential_labor_budget(budget);if estimate.payload->>'estimated_cents' is not null or estimate.payload->>'variance_cents' is not null or (estimate.payload->>'missing_rates')::integer<>1 then raise exception 'Missing rate presented as zero or complete';end if;
 perform set_config('request.jwt.claim.sub',admin_user::text,true);denied:=false;begin perform public.evaluate_essential_labor_budget(budget);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Admin without compensation read budgets';end if;
 perform set_config('request.jwt.claim.sub',emp::text,true);if exists(select 1 from public.essential_labor_budgets where company_id=c) or exists(select 1 from public.essential_budget_evaluations where company_id=c) then raise exception 'Employee budget RLS leak';end if;execute 'reset role';
end $$;
rollback;
